//! `veneer internal feature`: installs one Dev Container Feature
//! (https://containers.dev/implementors/features/). Generated by the devcontainer.json
//! adapter as a build hook; also usable directly.
//!
//! The feature is pulled as an OCI artifact (or read from a local directory), its option
//! defaults from `devcontainer-feature.json` are overlaid with `--option`s, and
//! `install.sh` runs as root with options as upper-cased environment variables. The
//! feature's `containerEnv` is recorded so `veneer exec`/`env`/hooks see it.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode};

use veneer_plan::Dirs;
use veneer_resolve::oci;

#[derive(Debug, clap::Args)]
pub struct FeatureArgs {
    /// OCI reference (ghcr.io/devcontainers/features/node:1) or local directory.
    pub id: String,
    /// Directory local feature paths are relative to.
    #[arg(long)]
    pub base: Option<PathBuf>,
    /// Feature option (repeatable): --option version=22.
    #[arg(long = "option", value_name = "NAME=VALUE")]
    pub options: Vec<String>,
}

#[derive(Debug, clap::Subcommand)]
pub enum Internal {
    /// Install a Dev Container Feature.
    Feature(FeatureArgs),
    /// Copy this binary to DEST (Kubernetes init containers from the scratch image).
    CopySelf { dest: std::path::PathBuf },
}

fn env_name(option: &str) -> String {
    option
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() {
                c.to_ascii_uppercase()
            } else {
                '_'
            }
        })
        .collect()
}

/// Path of the recorded feature `containerEnv` (read by `veneer_steps::command_env`).
pub fn feature_env_path(dirs: &Dirs) -> PathBuf {
    dirs.state.join("features").join("env.json")
}

fn fetch(dirs: &Dirs, id: &str, base: Option<&Path>) -> Result<PathBuf, String> {
    if id.starts_with("./") || id.starts_with("../") || id.starts_with('/') {
        let dir = base.unwrap_or(Path::new(".")).join(id);
        return dir
            .canonicalize()
            .map_err(|e| format!("local feature {}: {e}", dir.display()));
    }
    let reference = oci::Reference::parse(id)?;
    let dir = oci::cache_dir(&dirs.cache.join("features"), &reference);
    oci::pull(&reference, &dir)?;
    // Features ship as one tarball layer; some tarballs nest a top-level directory.
    if dir.join("install.sh").is_file() {
        return Ok(dir);
    }
    std::fs::read_dir(&dir)
        .map_err(|e| e.to_string())?
        .filter_map(Result::ok)
        .map(|e| e.path())
        .find(|p| p.join("install.sh").is_file())
        .ok_or_else(|| format!("feature {id} has no install.sh"))
}

pub fn run(cmd: Internal) -> ExitCode {
    let args = match cmd {
        Internal::Feature(args) => args,
        Internal::CopySelf { dest } => return copy_self(&dest),
    };
    let dirs = Dirs::from_env();
    let dir = match fetch(&dirs, &args.id, args.base.as_deref()) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("error: cannot fetch feature `{}`: {e}", args.id);
            return ExitCode::from(3);
        }
    };
    let meta: serde_json::Value = std::fs::read(dir.join("devcontainer-feature.json"))
        .ok()
        .and_then(|b| serde_json::from_slice(&b).ok())
        .unwrap_or_default();
    let mut env: BTreeMap<String, String> = BTreeMap::new();
    if let Some(opts) = meta["options"].as_object() {
        for (k, spec) in opts {
            if let Some(d) = spec.get("default") {
                let v = d
                    .as_str()
                    .map(str::to_string)
                    .unwrap_or_else(|| d.to_string());
                env.insert(env_name(k), v);
            }
        }
    }
    for o in &args.options {
        if let Some((k, v)) = o.split_once('=') {
            env.insert(env_name(k), v.to_string());
        }
    }
    let user = std::env::var("USER").unwrap_or_else(|_| "root".into());
    let home = std::env::var("HOME").unwrap_or_else(|_| "/root".into());
    for (k, v) in [
        ("_REMOTE_USER", &user),
        ("_CONTAINER_USER", &user),
        ("_REMOTE_USER_HOME", &home),
        ("_CONTAINER_USER_HOME", &home),
    ] {
        env.entry(k.into()).or_insert_with(|| v.clone());
    }
    let shell = if Path::new("/bin/bash").is_file() {
        "/bin/bash"
    } else {
        "/bin/sh"
    };
    let mut c = if veneer_plan::is_root() {
        Command::new(shell)
    } else {
        let mut s = Command::new("sudo");
        s.args(["-n", "-E", shell]);
        s
    };
    c.arg("install.sh").current_dir(&dir).envs(&env);
    eprintln!(
        "▸ feature {} ({})",
        meta["id"].as_str().unwrap_or(&args.id),
        dir.display()
    );
    match c.status() {
        Ok(s) if s.success() => {}
        Ok(s) => {
            eprintln!("error: feature `{}` install.sh exited with {s}", args.id);
            return ExitCode::from(3);
        }
        Err(e) => {
            eprintln!("error: cannot run install.sh: {e}");
            return ExitCode::from(3);
        }
    }
    if let Some(ce) = meta["containerEnv"].as_object() {
        let path = feature_env_path(&dirs);
        let mut all: BTreeMap<String, String> = std::fs::read(&path)
            .ok()
            .and_then(|b| serde_json::from_slice(&b).ok())
            .unwrap_or_default();
        for (k, v) in ce {
            if let Some(v) = v.as_str() {
                all.insert(k.clone(), v.to_string());
            }
        }
        let bytes = serde_json::to_vec_pretty(&all).unwrap();
        if let Err(e) = veneer_exec::write_atomic(&path, &bytes) {
            eprintln!("error: cannot record feature env: {e}");
            return ExitCode::from(1);
        }
    }
    ExitCode::SUCCESS
}

fn copy_self(dest: &std::path::Path) -> ExitCode {
    use std::os::unix::fs::PermissionsExt;
    let result = std::env::current_exe().and_then(|exe| {
        if let Some(d) = dest.parent() {
            std::fs::create_dir_all(d)?;
        }
        std::fs::copy(exe, dest)?;
        std::fs::set_permissions(dest, std::fs::Permissions::from_mode(0o755))
    });
    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: cannot copy veneer to {}: {e}", dest.display());
            ExitCode::from(1)
        }
    }
}
